// CNAPS runtime scales with source length — a fixed Wait either stalls short
// videos or times out long ones. Whisper is the long pole; ~4 min of processing
// per minute of source is what we measured. Drive only reports duration for
// files it has finished analysing, so fall back to the minimum when it is absent.
const cfg  = $('Settings').first().json;
const file = $('A new video lands in Drive').first().json;

// Guard: writing clips back into the watched folder makes the trigger fire on its
// own output, forever. Fail loudly here rather than let that start.
const watchedFolder = Array.isArray(file?.parents) ? file.parents[0] : null;
if (watchedFolder && cfg.output_folder_id && watchedFolder === cfg.output_folder_id) {
  throw new Error(
    'output_folder_id in Settings is the same folder the trigger watches (' + watchedFolder +
    '). Saving clips there would re-trigger this workflow on its own output. ' +
    'Point output_folder_id at a different folder.'
  );
}

const durationMs = Number(file?.videoMediaMetadata?.durationMillis ?? 0);
const sourceMin  = durationMs > 0 ? durationMs / 60000 : null;

let waitMinutes;
if (sourceMin) {
  waitMinutes = Math.ceil(sourceMin * cfg.wait_minutes_per_source_minute);
} else {
  waitMinutes = cfg.min_wait_minutes;
}
waitMinutes = Math.min(cfg.max_wait_minutes, Math.max(cfg.min_wait_minutes, waitMinutes));

return [{ json: {
  file_id: file.id,
  file_name: file.name,
  source_minutes: sourceMin ? Number(sourceMin.toFixed(2)) : null,
  wait_minutes: waitMinutes,
  wait_basis: sourceMin ? 'measured from Drive metadata' : 'no duration on the file, used min_wait_minutes',
}}];

// The upload URL is a 64-character secret. Never route a secret through an LLM —
// one mistyped character produces a URL that looks perfect and 404s with
// "Upload session not found or expired". So this is plain HTTP + a regex, no agent.
// The MCP endpoint answers in SSE framing ("event: message\ndata: {...}"), so the
// JSON has to be pulled out of the body text rather than read as a field.
const body = $input.first().json;
const raw  = typeof body === 'string' ? body : JSON.stringify(body);
const m    = raw.match(/https:\/\/mcp\.cnaps\.ai\/upload\/[a-f0-9]{64}/);

if (!m) {
  throw new Error('CNAPS did not return an upload URL. Response was: ' + raw.slice(0, 400));
}
return [{ json: { upload_url: m[0] } }];

// CNAPS returns the finished clips as one list document. Flatten it into one n8n
// item per clip so the loop below can upload and log each one independently.
// Each item already carries everything the sheet needs — no second lookup.
const cfg    = $('Settings').first().json;
const meta   = $('Work out how long to wait').first().json;
const listed = $input.first().json ?? {};
const items  = Array.isArray(listed.items) ? listed.items : [];

if (items.length === 0) {
  return [{ json: {
    ok: false,
    reason: listed.error ? String(listed.error).slice(0, 300)
                         : 'CNAPS returned no clips — the run may still have been going when the Wait expired',
    source_name: meta.file_name,
    clip_count: 0,
  }}];
}

return items.map((clip, i) => ({ json: {
  ok: true,
  source_name:   meta.file_name,
  source_file_id: meta.file_id,
  clip_index:    clip.index ?? i,
  title:         clip.label ?? `Clip ${i + 1}`,
  span:          clip.span ?? null,
  start_sec:     clip.source_start ?? null,
  end_sec:       clip.source_end ?? null,
  duration_sec:  (clip.source_end != null && clip.source_start != null)
                   ? Number((clip.source_end - clip.source_start).toFixed(2)) : null,
  camera:        clip.authored?.camera ?? null,
  cnaps_url:     clip.url,
  clip_count:    items.length,
  output_folder_id: cfg.output_folder_id,
}}));

