// Report what actually happened, read back from the nodes that did the work —
// never assume a step succeeded just because the workflow reached this point.
function outcome(nodeName) {
  try {
    const out = $(nodeName).first().json;
    if (!out) return null;
    if (out.error) return { ok: false, error: String(out.error).slice(0, 200) };
    if (out.ok === false) return { ok: false, error: out.error ?? 'node reported ok:false' };
    return { ok: true };
  } catch (e) { return null; }
}

const meta  = $('Work out how long to wait').first().json;
const clips = $('One row per clip').all().map(i => i.json).filter(c => c.ok);
const notified = outcome('Tell the team it\'s ready') ?? outcome('Say what went wrong');

return [{ json: {
  source_video:  meta.file_name,
  source_minutes: meta.source_minutes,
  wait_minutes:  meta.wait_minutes,
  wait_basis:    meta.wait_basis,
  clips_made:    clips.length,
  clips: clips.map(c => ({ title: c.title, span: c.span, seconds: c.duration_sec })),
  notified:      notified ? notified.ok : false,
  notify_error:  notified && !notified.ok ? notified.error : null,
}}];
